"""
DevPilot AI - Test Case Pydantic Schemas.
Defines structured data contracts for AI-generated test cases, validation results, and review requests.
"""

from typing import List, Dict, Any, Optional
from datetime import datetime
from pydantic import BaseModel, Field, ConfigDict


class GeneratedTestCaseItem(BaseModel):
    """Declarative test case representation generated by LLM and validated by Pydantic."""
    test_id_code: str = Field(..., description="Stable test identifier, e.g. TC-ORD-001")
    name: str = Field(..., description="Short descriptive test name")
    description: str = Field(..., description="Detailed description of the test scenario and intent")
    category: str = Field(
        ...,
        description="Category: positive, negative, boundary, security, regression",
        pattern="^(positive|negative|boundary|security|regression)$",
    )
    priority: str = Field(
        default="medium",
        pattern="^(critical|high|medium|low)$",
    )
    request_headers: Dict[str, str] = Field(default_factory=dict)
    path_params: Dict[str, Any] = Field(default_factory=dict)
    query_params: Dict[str, Any] = Field(default_factory=dict)
    request_body: Dict[str, Any] = Field(default_factory=dict)
    expected_status: int = Field(..., description="Expected HTTP status code grounded in contract")
    expected_response_checks: Dict[str, Any] = Field(
        default_factory=dict,
        description="Deterministic assertion rules (e.g. required keys, schema compliance)",
    )
    source_references: List[str] = Field(
        default_factory=list,
        description="Provenance references: Chunk IDs, Doc titles, or Bug IDs informing this test",
    )
    requires_review: bool = Field(
        default=False,
        description="Flagged as True if expected behavior is not strictly documented in contract",
    )


class TestGenerationRequest(BaseModel):
    """Payload to trigger test case generation for an endpoint."""
    endpoint_id: str = Field(..., description="UUID of target endpoint in database")
    testing_objective: str = Field(
        default="Generate comprehensive test cases covering positive, boundary, negative, and regression scenarios.",
        description="Natural language objective for the test generation session",
    )
    categories: List[str] = Field(
        default=["positive", "negative", "boundary", "security", "regression"],
        description="Filter which categories of test cases to generate",
    )
    model_override: Optional[str] = None


class TestCaseResponse(BaseModel):
    """API response model for persisted test cases."""
    id: str
    project_id: str
    endpoint_id: str
    test_id_code: str
    name: str
    description: Optional[str] = None
    category: str
    priority: str
    request_headers: Dict[str, str] = Field(default_factory=dict)
    path_params: Dict[str, Any] = Field(default_factory=dict)
    query_params: Dict[str, Any] = Field(default_factory=dict)
    request_body: Dict[str, Any] = Field(default_factory=dict)
    expected_status: int
    expected_response_checks: Dict[str, Any] = Field(default_factory=dict)
    source_references: List[str] = Field(default_factory=list)
    generation_model: str
    prompt_version: str
    requires_review: bool
    is_approved: bool
    is_active: bool
    created_at: datetime

    model_config = ConfigDict(from_attributes=True)


class TestCaseUpdateRequest(BaseModel):
    """Payload to approve, reject, or edit a test case."""
    name: Optional[str] = None
    description: Optional[str] = None
    priority: Optional[str] = None
    is_approved: Optional[bool] = None
    is_active: Optional[bool] = None
    requires_review: Optional[bool] = None
    expected_status: Optional[int] = None
    request_body: Optional[Dict[str, Any]] = None


class GenerationSessionResponse(BaseModel):
    """Response containing batch of generated and validated test cases."""
    project_id: str
    endpoint_id: str
    endpoint_path: str
    http_method: str
    model_used: str
    prompt_version: str
    retrieved_sources_count: int
    generated_test_cases: List[TestCaseResponse]
    validation_summary: Dict[str, Any]
